-- Blog redesign: cover icon, author and featured flag. Safe to run more than once.
-- Also loads/refreshes the 22 articles (existing slugs are updated, view counts are kept).
BEGIN;
ALTER TABLE cmr_admin.site_blog_post ADD COLUMN IF NOT EXISTS icon        varchar(8)  NOT NULL DEFAULT '📰';
ALTER TABLE cmr_admin.site_blog_post ADD COLUMN IF NOT EXISTS author      varchar(80) NOT NULL DEFAULT 'SyncTally Team';
ALTER TABLE cmr_admin.site_blog_post ADD COLUMN IF NOT EXISTS author_role varchar(80) NOT NULL DEFAULT 'Editorial';
ALTER TABLE cmr_admin.site_blog_post ADD COLUMN IF NOT EXISTS is_featured boolean    NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS ix_site_blog_featured ON cmr_admin.site_blog_post (is_featured) WHERE is_published AND is_featured;
ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, tag=EXCLUDED.tag, icon=EXCLUDED.icon, published_on=EXCLUDED.published_on,
  read_minutes=EXCLUDED.read_minutes, excerpt=EXCLUDED.excerpt, body=EXCLUDED.body,
  author=EXCLUDED.author, author_role=EXCLUDED.author_role, is_featured=EXCLUDED.is_featured;
COMMIT;
